// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

/// @notice Library for RLP encoding and contract address computation.
/// @author Solady (https://github.com/vectorized/solady/blob/main/src/utils/LibRLP.sol)
library LibRLP {
    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                          STRUCTS                            */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Defines a struct named `List` with a single field `_data`.
    /// @dev The `_data` field is a `uint256` value. The comment warns against modifying `_data` directly,
    /// suggesting that it should be managed through specific functions or logic.
    struct List {
        uint256 _data;
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                     ADDRESS COMPUTATION                    */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Computes the address of a contract that would be deployed by a specific deployer with a given nonce.
    /// @param deployer The address of the deployer.
    /// @param nonce The nonce used in the deployment.
    /// @return deployed The computed address of the contract that would be deployed.
    function computeAddress(address deployer, uint256 nonce) internal pure returns (address deployed) {
        /// @solidity memory-safe-assembly
        assembly {
            // Store the deployer address in scratch space.
            mstore(0x00, deployer)

            // If the nonce is below 0x80 (128).
            // prettier-ignore
            if lt(nonce, 0x80) {
                // Using the RLP encoding format:
                // 0xd6 = 0xc0 (list prefix) + 0x16 (length of [address, nonce])
                // 0x94 = 0x80 + 0x14 (20 bytes address length)
                mstore8(0x0b, 0xd6)
                mstore8(0x20, 0x94)
                mstore(0x21, nonce)
                deployed := keccak256(0x0b, 0x36)
                return
            }

            // prettier-ignore
            for { let i := 0x80 } 1 {} {
                i := add(i, 1)
                if iszero(shr(i, nonce)) { break }
            }

            // Store the `0xb8 + i` at scratch space.
            // `0xb8` is the offset for the length of the string.
            // `i` is the number of bytes of the nonce.
            mstore8(0x0b, add(0xd6, i))
            mstore8(0x20, add(0x94, i))

            // Right shift the deployer address by `i` bytes.
            // Store the shifted deployer address.
            mstore(0x21, shl(i, deployer))

            // Store the nonce.
            // The `shl(8, ...)` is to shift left by 1 byte for the `0x80` prefix.
            mstore(0x2d, shl(sub(160, mul(i, 8)), nonce))
            deployed := keccak256(0x0b, add(0x36, i))
        }
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                    LIST PUSH FUNCTIONS                      */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Creates an empty list.
    /// @return result The empty list.
    function p() internal pure returns (List memory result) {
        result._data = 0x800000000000;
    }

    /// @notice Appends a `uint256` value to the list.
    /// @param x The value to append.
    /// @return result The updated list.
    function p(uint256 x) internal pure returns (List memory result) {
        result._data = shl(48, x);
        _updateTail(result, result);
    }

    /// @notice Appends an `address` value to the list.
    /// @param x The value to append.
    /// @return result The updated list.
    function p(address x) internal pure returns (List memory result) {
        result._data = shl(48, uint256(uint160(x)));
        _updateTail(result, result);
    }

    /// @notice Appends a `bool` value to the list.
    /// @param x The value to append.
    /// @return result The updated list.
    function p(bool x) internal pure returns (List memory result) {
        result._data = shl(48, uint256(x));
        _updateTail(result, result);
    }

    /// @notice Appends a `bytes` value to the list.
    /// @param x The value to append.
    /// @return result The updated list.
    function p(bytes memory x) internal pure returns (List memory result) {
        result._data = shl(48, uint256(bytes32(x)));
        _updateTail(result, result);
    }

    /// @notice Appends a nested `List` to the list.
    /// @param x The list to append.
    /// @return result The updated list.
    function p(List memory x) internal pure returns (List memory result) {
        result._data = shl(48, x._data);
        _updateTail(result, result);
    }

    /// @notice Appends a `uint256` value to an existing list.
    /// @param list The list to append to.
    /// @param x The value to append.
    /// @return result The updated list.
    function p(List memory list, uint256 x) internal pure returns (List memory result) {
        result._data = shl(48, x);
        _updateTail(list, result);
    }

    /// @notice Appends an `address` value to an existing list.
    /// @param list The list to append to.
    /// @param x The value to append.
    /// @return result The updated list.
    function p(List memory list, address x) internal pure returns (List memory result) {
        result._data = shl(48, uint256(uint160(x)));
        _updateTail(list, result);
    }

    /// @notice Appends a `bool` value to an existing list.
    /// @param list The list to append to.
    /// @param x The value to append.
    /// @return result The updated list.
    function p(List memory list, bool x) internal pure returns (List memory result) {
        result._data = shl(48, uint256(x));
        _updateTail(list, result);
    }

    /// @notice Appends a `bytes` value to an existing list.
    /// @param list The list to append to.
    /// @param x The value to append.
    /// @return result The updated list.
    function p(List memory list, bytes memory x) internal pure returns (List memory result) {
        result._data = shl(48, uint256(bytes32(x)));
        _updateTail(list, result);
    }

    /// @notice Appends a nested `List` to an existing list.
    /// @param list The list to append to.
    /// @param x The list to append.
    /// @return result The updated list.
    function p(List memory list, List memory x) internal pure returns (List memory result) {
        result._data = shl(48, x._data);
        _updateTail(list, result);
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                    ENCODE FUNCTIONS                         */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Encodes a list into RLP format.
    /// @param list The list to encode.
    /// @return result The encoded bytes.
    function encode(List memory list) internal pure returns (bytes memory result) {
        assembly {
            let m := mload(0x40)
            result := m

            let totalLen := 0
            let d := mload(list)

            // Traverse the linked list and encode each item.
            for {} 1 {} {
                let v := and(shr(48, d), 0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff)
                let i := 0

                // Determine the length of the encoded value.
                switch shr(248, v)
                case 0 {
                    i := 0
                }
                default {
                    let n := 0
                    for {} shr(n, v) { n := add(n, 8) } {}
                    n := shr(3, n)
                    i := n
                }

                // Store the encoded value.
                mstore(add(m, add(1, totalLen)), shl(sub(256, mul(i, 8)), v))
                totalLen := add(totalLen, i)

                // Move to the next item in the linked list.
                d := mload(add(list, 0x20))
                if iszero(d) { break }
                list := add(list, 0x20)
            }

            // Store the length prefix.
            if lt(totalLen, 0x38) {
                mstore8(m, add(0xc0, totalLen))
                mstore(add(m, add(1, totalLen)), 0)
                result := m
                mstore(0x40, add(m, add(1, add(totalLen, 0x20))))
            }
            if gt(totalLen, 0x37) {
                let l := 0
                for {} shr(l, totalLen) { l := add(l, 8) } {}
                l := shr(3, l)

                // Store the length of the length.
                mstore8(m, add(0xf7, l))
                mstore(add(m, 1), shl(sub(256, mul(l, 8)), totalLen))
                mstore(add(m, add(1, add(l, totalLen))), 0)
                result := add(m, l)
                mstore(0x40, add(m, add(1, add(l, add(totalLen, 0x20)))))
            }
        }
    }

    /// @notice Encodes a `uint256` value into RLP format.
    /// @param x The value to encode.
    /// @return result The encoded bytes.
    function encode(uint256 x) internal pure returns (bytes memory result) {
        assembly {
            let m := mload(0x40)
            result := m

            if iszero(x) {
                mstore8(m, 0x80)
                mstore(0x40, add(m, 0x20))
                return
            }

            let i := 0
            for {} shr(i, x) { i := add(i, 8) } {}
            i := shr(3, i)

            if iszero(gt(i, 1)) {
                mstore8(m, x)
                mstore(0x40, add(m, 0x20))
                return
            }

            mstore8(m, add(0x80, i))
            mstore(add(m, 1), shl(sub(256, mul(i, 8)), x))
            mstore(0x40, add(m, add(0x20, add(1, i))))
        }
    }

    /// @notice Encodes an `address` value into RLP format.
    /// @param x The address to encode.
    /// @return result The encoded bytes.
    function encode(address x) internal pure returns (bytes memory result) {
        assembly {
            let m := mload(0x40)
            result := m

            mstore8(m, 0x94)
            mstore(add(m, 0x01), x)
            mstore(0x40, add(m, 0x21))
        }
    }

    /// @notice Encodes a `bool` value into RLP format.
    /// @param x The bool to encode.
    /// @return result The encoded bytes.
    function encode(bool x) internal pure returns (bytes memory result) {
        assembly {
            let m := mload(0x40)
            result := m
            mstore8(m, x)
            mstore(0x40, add(m, 0x20))
        }
    }

    /// @notice Encodes a `bytes` value into RLP format.
    /// @param x The bytes to encode.
    /// @return result The encoded bytes.
    function encode(bytes memory x) internal pure returns (bytes memory result) {
        assembly {
            let m := mload(0x40)
            result := m
            let len := mload(x)

            // Empty bytes.
            if iszero(len) {
                mstore8(m, 0x80)
                mstore(0x40, add(m, 0x20))
                return
            }

            // Single byte less than 0x80.
            if and(iszero(gt(len, 1)), lt(byte(0, x), 0x80)) {
                mstore8(m, byte(0, x))
                mstore(0x40, add(m, 0x20))
                return
            }

            // Length is 2-55 bytes.
