    );
    assertEq(
        LibRLP.encode(LibRLP.p().p(_repeatFF(55))), abi.encodePacked(hex"f838b7", _repeatFF(55))
    );
    assertEq(
        LibRLP.encode(LibRLP.p().p(_repeatFF(56))),
        abi.encodePacked(hex"f83ab838", _repeatFF(56))
    );
    assertEq(
        LibRLP.encode(LibRLP.p().p(_repeatFF(57))),
