function _repeatFF(uint256 n) internal pure returns (bytes memory result) {
    /// @solidity memory-safe-assembly
    assembly {
        result := mload(0x40)
        mstore(result, n)
        for { let i := 0 } lt(i, n) { i := add(i, 0x20) } {
            mstore(add(add(result, 0x20), i), not(0))
        }
        mstore(0x40, add(add(result, 0x20), n))
    }
}
