function testSmallLog256Equivalence(uint256 n) public {
    n = _bound(n, 0, 0xffffffff);
    assertEq(_smallLog256(n), FixedPointMathLib.log256(n));
    assertEq(_smallLog256(n), _smallLog256Simple(n));
